.hero-section {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 90vh;
  background-color: var(--color-bg);
  text-align: center;
  padding: 4rem 2rem;
}

.hero-inner {
  max-width: 720px;
}

.hero-name {
  font-family: var(--font-heading);
  font-size: 4rem;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 0.75rem;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.hero-role {
  font-family: var(--font-body);
  font-size: 1.25rem;
  color: var(--color-text-muted);
  margin: 0 0 1.5rem;
  font-weight: 400;
}

.hero-tagline {
  font-family: var(--font-body);
  font-size: 1.125rem;
  color: var(--color-text-muted);
  margin: 0;
  line-height: 1.7;
  max-width: 540px;
  margin-left: auto;
  margin-right: auto;
}

@media (max-width: 768px) {
  .hero-name {
    font-size: 2.5rem;
  }

  .hero-role {
    font-size: 1.1rem;
  }

  .hero-section {
    min-height: 70vh;
    padding: 3rem 1.5rem;
  }
}

.projects-section {
  padding: 6rem 2rem;
  background-color: var(--color-surface);
}

.projects-inner {
  max-width: 1100px;
  margin: 0 auto;
}

.projects-title {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 3rem;
  letter-spacing: -0.01em;
}

.projects-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2.5rem;
}

.project-card {
  text-decoration: none;
  color: inherit;
  display: block;
  border-radius: 8px;
  overflow: hidden;
  background: var(--color-bg);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.project-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.08);
}

.project-image-wrap {
  position: relative;
  overflow: hidden;
  aspect-ratio: 16 / 10;
  background-color: #e8e8e8;
}

.project-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.project-image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #e0e0e0 0%, #cfcfcf 100%);
}

.project-overlay {
  position: absolute;
  inset: 0;
  background: rgba(26, 26, 26, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.project-card:hover .project-overlay {
  opacity: 1;
}

.project-view {
  color: #ffffff;
  font-family: var(--font-body);
  font-size: 0.95rem;
  font-weight: 500;
  letter-spacing: 0.03em;
}

.project-info {
  padding: 1.5rem;
}

.project-name {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--color-text);
  margin: 0 0 0.5rem;
}

.project-desc {
  font-family: var(--font-body);
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin: 0;
  line-height: 1.6;
}

@media (max-width: 768px) {
  .projects-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .projects-section {
    padding: 4rem 1.5rem;
  }

  .projects-title {
    font-size: 1.75rem;
  }
}

.about-section {
  padding: 6rem 2rem;
  background-color: var(--color-bg);
}

.about-inner {
  max-width: 1100px;
  margin: 0 auto;
}

.about-title {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 3rem;
  letter-spacing: -0.01em;
}

.about-layout {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 3rem;
  align-items: start;
}

.about-image {
  width: 100%;
  border-radius: 8px;
  display: block;
}

.about-image-placeholder {
  width: 100%;
  aspect-ratio: 4 / 5;
  background: linear-gradient(135deg, #e0e0e0 0%, #cfcfcf 100%);
  border-radius: 8px;
}

.about-bio {
  font-family: var(--font-body);
  font-size: 1.05rem;
  color: var(--color-text);
  line-height: 1.75;
}

.about-bio p {
  margin: 0 0 1rem;
}

.about-bio p:last-child {
  margin-bottom: 0;
}

.about-skills {
  margin-top: 2rem;
}

.skills-heading {
  font-family: var(--font-heading);
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-text);
  margin: 0 0 1rem;
}

.skills-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.skill-tag {
  font-family: var(--font-body);
  font-size: 0.85rem;
  color: var(--color-text-muted);
  background: var(--color-surface);
  border: 1px solid #e0e0e0;
  padding: 0.35rem 0.85rem;
  border-radius: 100px;
}

@media (max-width: 768px) {
  .about-layout {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .about-section {
    padding: 4rem 1.5rem;
  }

  .about-title {
    font-size: 1.75rem;
  }

  .about-image-placeholder {
    max-width: 320px;
  }
}

.contact-section {
  padding: 6rem 2rem;
  background-color: var(--color-surface);
  text-align: center;
}

.contact-inner {
  max-width: 600px;
  margin: 0 auto;
}

.contact-title {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 1.5rem;
  letter-spacing: -0.01em;
}

.contact-message {
  font-family: var(--font-body);
  font-size: 1.1rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin: 0 0 2rem;
}

.contact-email-link {
  font-family: var(--font-body);
  font-size: 1.25rem;
  color: var(--color-accent);
  text-decoration: none;
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: 0.15rem;
  transition: opacity 0.2s ease;
}

.contact-email-link:hover {
  opacity: 0.7;
}

@media (max-width: 768px) {
  .contact-section {
    padding: 4rem 1.5rem;
  }

  .contact-title {
    font-size: 1.75rem;
  }

  .contact-email-link {
    font-size: 1.1rem;
  }
}

sharedCss:
:root {
  --color-bg: #fafafa;
  --color-surface: #ffffff;
  --color-accent: #2d2d2d;
  --color-text: #1a1a1a;
  --color-text-muted: #666666;
  --font-heading: 'Georgia', serif;
  --font-body: system-ui, -apple-system, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
}
